css:
.cat-list-header{display:grid;grid-template-columns:1.6fr 1fr 1fr;padding:10px 20px 8px;border-bottom:1px solid var(--cat-color-stroke-softer)}
.cat-list-header span{font:500 var(--cat-font-size-xs) var(--cat-font-family-ui);letter-spacing:.04em;text-transform:uppercase;color:var(--cat-color-ink-low)}
.cat-group-head{padding:16px 20px 6px;font:600 var(--cat-font-size-xs) var(--cat-font-family-ui);letter-spacing:.05em;text-transform:uppercase;color:var(--cat-color-ink-low)}
.cat-row{display:grid;grid-template-columns:1.6fr 1fr 1fr;align-items:center;height:var(--cat-semantic-row-height,38px);padding:0 12px;margin:0 8px;border-radius:var(--cat-size-radius-sm);font-size:var(--cat-font-size-base);cursor:default;transition:background 100ms ease-out}
.cat-row:nth-child(n) .cell-type,.cat-row .cell-date{font-size:var(--cat-font-size-sm);color:var(--cat-color-ink-mid);padding-right:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cell-name{color:var(--cat-color-ink-hi);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cat-row:hover{background:rgba(0,0,0,.04)}
.cat-row.selected,.cat-row.is-selected{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base))}
.cat-row.selected .cell-name,.cat-row.selected .cell-type,.cat-row.selected .cell-date{color:var(--cat-color-surface-selected-on-accent)}
.cat-statusbar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:9px 18px;border-top:1px solid var(--cat-color-stroke-dark);background:rgba(255,255,255,.5);backdrop-filter:blur(12px);font-family:var(--cat-font-family-ui)}
.cat-status-title{font-size:var(--cat-font-size-md);font-weight:var(--cat-font-weight-demibold);color:var(--cat-color-ink-hi)}
.cat-status-meta{font-size:var(--cat-font-size-xs);color:var(--cat-color-ink-low)}
.cat-status-count{font-size:var(--cat-font-size-xs);color:var(--cat-color-ink-mid)}
